-- fx_modifiers gets the stat a modifier's amount is counted onto: the game module's calculator reads plain stats
-- (attack_speed_+%), and a conditional stat (attack_speed_+%_when_on_low_life) is added to its plain one while its
-- conditions hold. counts_as is that plain stat; NULL when the stat is itself what the calculator reads.
-- A condition in fx_modifiers.conditions may carry "not": true ("if you haven't been Hit Recently").
ALTER TABLE fx_modifiers ADD COLUMN counts_as TEXT;
-- The conditions the game module answers today for a stat's own condition (StatConditions.cs, from what
-- ItemConditionFlags and the recent events publish). The names are the module's own.
